import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.C4u0TEY0.js";const u=JSON.parse('{"title":"DEX interpreter","description":"","frontmatter":{},"headers":[],"relativePath":"internals/dex.md","filePath":"internals/dex.md"}'),s={name:"internals/dex.md"};function i(n,e,c,d,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="dex-interpreter" tabindex="-1">DEX interpreter <a class="header-anchor" href="#dex-interpreter" aria-label="Permalink to &quot;DEX interpreter&quot;">​</a></h1><h2 id="file-structure" tabindex="-1">File structure <a class="header-anchor" href="#file-structure" aria-label="Permalink to &quot;File structure&quot;">​</a></h2><p>A DEX file carries a header, then tables for strings, types, prototypes, fields, methods and classes. apk.js reads all of them in one pass and keeps index-addressable arrays. Multi-dex APKs (<code>classes2.dex</code>, <code>classes3.dex</code>, …) are loaded into a single class registry, so cross-dex references resolve.</p><h2 id="bytecode-execution" tabindex="-1">Bytecode execution <a class="header-anchor" href="#bytecode-execution" aria-label="Permalink to &quot;Bytecode execution&quot;">​</a></h2><p><code>DexInterpreter.execute</code> allocates a register file sized by the method&#39;s <code>registersSize</code>, copies parameters into the tail end, and runs a program counter over the instruction stream.</p><p>Instructions are decoded by their 8-bit opcode. Invoke instructions (<code>0x6e</code>–<code>0x78</code>) read their argument registers, resolve the method reference, and hand the call to <code>JavaVM.invoke</code>. The result lands in <code>pendingResult</code> and the next <code>move-result</code> instruction picks it up.</p><h2 id="method-resolution" tabindex="-1">Method resolution <a class="header-anchor" href="#method-resolution" aria-label="Permalink to &quot;Method resolution&quot;">​</a></h2><p><code>JavaVM.invoke</code> resolves in this order:</p><ol><li>Native definition registered for the class — framework and Java core classes.</li><li>DEX method on the resolved class, walking up the superclass chain.</li><li>Interface methods for <code>invoke-interface</code>.</li></ol><p>Calls into unimplemented native methods raise a <code>VMRuntimeError</code>, which becomes a Java exception the app can catch.</p><h2 id="exceptions" tabindex="-1">Exceptions <a class="header-anchor" href="#exceptions" aria-label="Permalink to &quot;Exceptions&quot;">​</a></h2><p>Handlers come from the method&#39;s catch table. When a call throws, the interpreter walks the table for a matching handler at the current PC, moves the PC to the handler, and stores the exception object in the handler&#39;s register. If nothing matches, the exception propagates up the stack.</p><h2 id="field-access" tabindex="-1">Field access <a class="header-anchor" href="#field-access" aria-label="Permalink to &quot;Field access&quot;">​</a></h2><p>Fields resolve through the class registry. Instance fields live in a per-object map keyed by <code>classDesc-&gt;name:type</code>; inherited fields resolve by walking up the class chain. Static fields live on the runtime class and initialize once.</p>',14)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
